package com.example.demo.service;

import com.example.demo.entity.Customer;
import com.example.demo.repo.CustomerRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class CustomerServiceTest {

    private CustomerRepository repository;
    private CustomerService service;

    @BeforeEach
    public void setUp() {
        repository = mock(CustomerRepository.class);
        service = new CustomerService(repository);
    }

    @Test
    public void testFindAll() {
        List<Customer> customers = Arrays.asList(
                new Customer("Alice", "alice@example.com"),
                new Customer("Bob", "bob@example.com"));
        when(repository.findAll()).thenReturn(customers);

        List<Customer> result = service.findAll();

        assertEquals(2, result.size());
        verify(repository).findAll();
    }

    @Test
    public void testFindById() {
        Customer customer = new Customer("Alice", "alice@example.com");
        when(repository.findById(1L)).thenReturn(Optional.of(customer));

        Optional<Customer> result = service.findById(1L);

        assertTrue(result.isPresent());
        assertEquals("Alice", result.get().getName());
    }

    @Test
    public void testSave() {
        Customer customer = new Customer("Carol", "carol@example.com");
        when(repository.save(customer)).thenReturn(customer);

        Customer result = service.save(customer);

        assertEquals("Carol", result.getName());
        verify(repository).save(customer);
    }

    @Test
    public void testDeleteById() {
        service.deleteById(5L);
        verify(repository).deleteById(5L);
    }
}
